mapper.select:


	is_delete = 0

		AND menu_name like concat('%', #{menuName}, '%')


		AND visible = #{visible}


		AND status = #{status}


		AND (client_type = #{clientType} or client_type = 'all')


order by parent_id, order_num

select distinct m.menu_id, m.parent_id, m.menu_name, m.path, m.component, m.`query`, m.route_name, m.visible, m.status, ifnull(m.perms,'') as perms, ifnull(m.client_type, 'admin') as client_type, m.is_frame, m.is_cache, m.menu_type, m.icon, m.order_num, m.create_time from sys_menu m left join sys_role_menu rm on m.menu_id = rm.menu_id and rm.is_delete = 0 left join sys_user_role ur on rm.role_id = ur.role_id and ur.is_delete = 0 left join sys_role ro on ur.role_id = ro.role_id and ro.is_delete = 0 where ur.user_id = #{params.userId} and m.is_delete = 0
AND m.menu_name like concat('%', #{menuName}, '%')
AND m.visible = #{visible}
AND m.status = #{status}
AND (m.client_type = #{clientType} or m.client_type = 'all')
order by m.parent_id, m.order_num
